//! FTS5 cross-engine regression tests (step 5f). GENERATED by target/perf-work/step5f/gen/gen_tests.py:
//! every expected value below is what the C SQLite 3.54.1 CLI returns for the same statements, and the
//! `image` statements are the shadow-table rows (`%_data`, `%_idx`, `%_config`, `%_docsize`, `%_content`)
//! that C wrote. Nothing here depends on files outside the repository.
use crate::Connection;
use sqliters_types::Value;

struct Case {
    /// Statements run by this engine to create the tables.
    create: &'static [&'static str],
    /// Statements run by this engine to fill them (empty when `image` is used).
    writes: &'static [&'static str],
    /// The shadow-table rows written by C for `create` + the case's writes.
    image: &'static [&'static str],
    /// `(statement, rows C returns)`; an expectation starting with `ERR:` is the error message.
    checks: &'static [(&'static str, &'static str)],
    /// Statements run by this engine after `checks`, followed by `checks_after`.
    post: &'static [&'static str],
    checks_after: &'static [(&'static str, &'static str)],
}

fn render(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Integer(i) => i.to_string(),
        Value::Text(s) => s.clone(),
        Value::Blob(b) => String::from_utf8_lossy(b).into_owned(),
        other => format!("{}", other.to_real_lossy()),
    }
}

fn answer(conn: &Connection, sql: &str) -> String {
    match conn.query(sql, &[]) {
        Ok(res) => res
            .rows
            .iter()
            .map(|r| r.values().iter().map(render).collect::<Vec<_>>().join("|"))
            .collect::<Vec<_>>()
            .join("\n"),
        Err(e) => format!("ERR:{}", e.message),
    }
}

fn run_case(case: &Case) {
    let conn = Connection::open_in_memory().unwrap();
    for sql in case.create.iter().chain(case.writes).chain(case.image) {
        conn.execute(sql).unwrap_or_else(|e| panic!("{sql}: {e:?}"));
    }
    for (sql, want) in case.checks {
        assert_eq!(answer(&conn, sql), *want, "{sql}");
    }
    for sql in case.post {
        conn.execute(sql).unwrap_or_else(|e| panic!("{sql}: {e:?}"));
    }
    for (sql, want) in case.checks_after {
        assert_eq!(answer(&conn, sql), *want, "after post: {sql}");
    }
}

