/// F6 (write side): a row deleted and written again in one flush keeps the delete flag on its new entries (fts5HashAddPoslistSize: nPos*2+1, or 00 00 with detail=none) - the leaves equal C's byte for byte; C's secure-delete relies on the flag
#[test]
fn f6_bdel_write_full() {
    run_case(&Case {
        create: &[r#"CREATE VIRTUAL TABLE f USING fts5(a, detail=full);"#],
        writes: &[
            r#"INSERT INTO f(rowid,a) VALUES(1,'alpha beta'),(2,'beta');"#,
            r#"UPDATE f SET a='alpha gamma alpha' WHERE rowid=1;"#,
            r#"REPLACE INTO f(rowid,a) VALUES(2,'beta delta');"#,
        ],
        image: &[],
        checks: &[
            (
                r#"SELECT id >> 37, hex(block) FROM f_data WHERE id > 1000 ORDER BY id;"#,
                r#"1|0000001A0630616C706861010202010462657461010203010202040A
2|000000210630616C706861010502040104626574610101010567616D6D61010203040B08
3|00000017053062657461020302010564656C74610202030409"#,
            ),
            (
                r#"SELECT rowid FROM f WHERE f MATCH 'alpha OR beta' ORDER BY rowid;"#,
                r#"1
2"#,
            ),
            (r#"INSERT INTO f(f) VALUES('integrity-check');"#, r#""#),
        ],
        post: &[],
        checks_after: &[],
    });
}

