/// F4b: one position list of ~70 000 entries must be split across leaves (a leaf cannot exceed 65 535 bytes)
#[test]
fn f4b_big_poslist_own() {
    run_case(&Case {
        create: &[r#"CREATE VIRTUAL TABLE f USING fts5(x);"#],
        writes: &[
            r#"INSERT INTO f(rowid, x) SELECT 1, group_concat('rep', ' ') FROM (WITH RECURSIVE c(i) AS (SELECT 1 UNION ALL SELECT i+1 FROM c WHERE i<70000) SELECT i FROM c);"#,
            r#"INSERT INTO f(rowid, x) VALUES(2, 'aa rep bb');"#,
        ],
        image: &[],
        checks: &[
            (
                r#"SELECT rowid FROM f WHERE f MATCH 'rep' ORDER BY rowid;"#,
                r#"1
2"#,
            ),
            (r#"SELECT rowid FROM f WHERE f MATCH 'bb';"#, r#"2"#),
            (
                r#"SELECT count(*) FROM f WHERE f MATCH '"rep rep rep"';"#,
                r#"1"#,
            ),
            (r#"SELECT max(length(block)) < 65536 FROM f_data;"#, r#"1"#),
            (r#"INSERT INTO f(f) VALUES('integrity-check');"#, r#""#),
        ],
        post: &[],
        checks_after: &[],
    });
}

