/// F11: tokens of tokenize='' are exactly C's (fts5vocab) and its MATCH results agree
#[test]
fn f11_tokenizer_0() {
    run_case(&Case {
        create: &[
            r#"CREATE VIRTUAL TABLE f USING fts5(x);"#,
            r#"CREATE VIRTUAL TABLE v USING fts5vocab(f, 'instance');"#,
        ],
        writes: &[
            r#"INSERT INTO f(rowid, x) VALUES(1, 'Ünïcödé straße İstanbul søren đak łódź µm ſtop x² ½cup café a😀b ①x ㎏ ΣΊΣΥΦΟΣ ǅemal Ⅷ agreed caresses ponies relational hopping o''neil x-y a_b 3.14');"#,
        ],
        image: &[],
        checks: &[
            (
                r#"SELECT group_concat(term || ':' || offset, ' ') FROM (SELECT term, offset FROM v ORDER BY offset, term);"#,
                r#"unicode:0 straße:1 istanbul:2 søren:3 đak:4 łodz:5 μm:6 stop:7 x²:8 ½cup:9 cafe:10 a:11 b:12 ①x:13 σίσυφοσ:14 ǆemal:15 ⅷ:16 agreed:17 caresses:18 ponies:19 relational:20 hopping:21 o:22 neil:23 x:24 y:25 a:26 b:27 3:28 14:29"#,
            ),
            (
                r#"SELECT count(*) FROM f WHERE f MATCH '"unicode"';"#,
                r#"1"#,
            ),
            (r#"SELECT hex(sz) FROM f_docsize;"#, r#"1E"#),
            (
                r#"SELECT highlight(f, 0, '[', ']') FROM f WHERE f MATCH 'x*';"#,
                r#"Ünïcödé straße İstanbul søren đak łódź µm ſtop [x²] ½cup café a😀b ①x ㎏ ΣΊΣΥΦΟΣ ǅemal Ⅷ agreed caresses ponies relational hopping o'neil [x]-y a_b 3.14"#,
            ),
        ],
        post: &[],
        checks_after: &[],
    });
}

