/// F12: INSERT OR REPLACE / REPLACE / OR IGNORE / UPDATE OR REPLACE behave like C (fts5UpdateMethod + sqlite3_vtab_on_conflict)
#[test]
fn f12_conflict_clauses() {
    run_case(&Case {
        create: &[r#"CREATE VIRTUAL TABLE f USING fts5(a, b);"#],
        writes: &[
            r#"INSERT INTO f(rowid, a, b) VALUES(1, 'one', 'x'), (2, 'two', 'y'), (3, 'three', 'z');"#,
            r#"INSERT OR REPLACE INTO f(rowid, a, b) VALUES(2, 'deux', 'yy');"#,
            r#"REPLACE INTO f(rowid, a, b) VALUES(3, 'trois', 'zz');"#,
            r#"INSERT OR IGNORE INTO f(rowid, a, b) VALUES(1, 'ignored', 'q');"#,
            r#"INSERT OR IGNORE INTO f(rowid, a, b) VALUES(4, 'four', 'w');"#,
            r#"UPDATE OR REPLACE f SET rowid = 1, a = 'moved' WHERE rowid = 4;"#,
            r#"UPDATE OR IGNORE f SET rowid = 2 WHERE rowid = 3;"#,
            r#"UPDATE f SET rowid = 9 WHERE rowid = 3;"#,
        ],
        image: &[],
        checks: &[
            (
                r#"SELECT rowid, a, b FROM f ORDER BY rowid;"#,
                r#"1|moved|w
2|deux|yy
9|trois|zz"#,
            ),
            (
                r#"SELECT rowid FROM f WHERE f MATCH 'one OR two OR three OR ignored OR four';"#,
                r#""#,
            ),
            (
                r#"SELECT rowid FROM f WHERE f MATCH 'deux OR trois OR moved' ORDER BY rowid;"#,
                r#"1
2
9"#,
            ),
            (
                r#"INSERT INTO f(rowid, a, b) VALUES(1, 'dup', 'd');"#,
                r#"ERR:constraint failed"#,
            ),
            (
                r#"UPDATE f SET rowid = 2 WHERE rowid = 9;"#,
                r#"ERR:constraint failed"#,
            ),
            (
                r#"SELECT count(*), hex(block) FROM f_data WHERE id = 1;"#,
                r#"1|030303"#,
            ),
            (r#"INSERT INTO f(f) VALUES('integrity-check');"#, r#""#),
        ],
        post: &[],
        checks_after: &[],
    });
}

/// F13: contentless_unindexed=1 keeps the UNINDEXED columns in %_content exactly like C
#[test]
fn f13_contentless_unindexed_own() {
    run_case(&Case {
        create: &[
            r#"CREATE VIRTUAL TABLE f USING fts5(a, b UNINDEXED, c, content='', contentless_unindexed=1, contentless_delete=1);"#,
        ],
        writes: &[
            r#"INSERT INTO f(rowid, a, b, c) VALUES(1, 'alpha beta', 'meta one', 'gamma'), (2, 'beta', 'meta two', 'delta');"#,
            r#"UPDATE f SET b = 'meta changed' WHERE rowid = 2;"#,
            r#"INSERT INTO f(rowid, a, b, c) VALUES(3, 'alpha', NULL, 'zeta');"#,
            r#"DELETE FROM f WHERE rowid = 1;"#,
        ],
        image: &[],
        checks: &[
            (
                r#"SELECT rowid, a, b, c FROM f ORDER BY rowid;"#,
                r#"2||meta changed|
3|||"#,
            ),
            (
                r#"SELECT rowid, b FROM f WHERE f MATCH 'beta OR zeta' ORDER BY rowid;"#,
                r#"2|meta changed
3|"#,
            ),
            (
                r#"SELECT sql FROM sqlite_schema WHERE name = 'f_content';"#,
                r#"CREATE TABLE 'f_content'(id INTEGER PRIMARY KEY, c1)"#,
            ),
            (
                r#"SELECT * FROM f_content ORDER BY id;"#,
                r#"2|meta changed
3|"#,
            ),
            (
                r#"UPDATE f SET a = 'x' WHERE rowid = 2;"#,
                r#"ERR:cannot UPDATE a subset of columns on fts5 contentless-delete table: f"#,
            ),
            (
                r#"SELECT rowid, b FROM f WHERE rowid = 2;"#,
                r#"2|meta changed"#,
            ),
        ],
        post: &[],
        checks_after: &[],
    });
}

