/// special commands and configuration values are validated like C (sqlite3Fts5ConfigSetValue, fts5SpecialInsert)
#[test]
fn commands_and_config() {
    run_case(&Case {
        create: &[
            r#"CREATE VIRTUAL TABLE f USING fts5(a);"#,
            r#"CREATE VIRTUAL TABLE g USING fts5(a, content='');"#,
        ],
        writes: &[
            r#"INSERT INTO f(rowid, a) VALUES(1, 'x');"#,
            r#"INSERT INTO g(rowid, a) VALUES(1, 'x y');"#,
        ],
        image: &[],
        checks: &[
            (
                r#"INSERT INTO f(f, rank) VALUES('pgsz', 31);"#,
                r#"ERR:SQL logic error"#,
            ),
            (r#"INSERT INTO f(f, rank) VALUES('PGSZ', 1000);"#, r#""#),
            (
                r#"INSERT INTO f(f, rank) VALUES('automerge', 65);"#,
                r#"ERR:SQL logic error"#,
            ),
            (
                r#"INSERT INTO f(f, rank) VALUES('usermerge', 1);"#,
                r#"ERR:SQL logic error"#,
            ),
            (
                r#"INSERT INTO f(f, rank) VALUES('crisismerge', -1);"#,
                r#"ERR:SQL logic error"#,
            ),
            (
                r#"INSERT INTO f(f, rank) VALUES('hashsize', 0);"#,
                r#"ERR:SQL logic error"#,
            ),
            (
                r#"INSERT INTO f(f, rank) VALUES('deletemerge', 'x');"#,
                r#"ERR:SQL logic error"#,
            ),
            (
                r#"INSERT INTO f(f, rank) VALUES('secure-delete', 1);"#,
                r#""#,
            ),
            (
                r#"INSERT INTO f(f, rank) VALUES('rank', 'nosuchfn(1, 2)');"#,
                r#""#,
            ),
            (
                r#"INSERT INTO f(f, rank) VALUES('rank', 'bm25(');"#,
                r#"ERR:SQL logic error"#,
            ),
            (
                r#"INSERT INTO f(f) VALUES('nosuchcommand');"#,
                r#"ERR:SQL logic error"#,
            ),
            (
                r#"INSERT INTO f(f) VALUES('delete-all');"#,
                r#"ERR:'delete-all' may only be used with a contentless or external content fts5 table"#,
            ),
            (r#"INSERT INTO f(f) VALUES('OPTIMIZE');"#, r#""#),
            (r#"INSERT INTO f(f) VALUES('flush');"#, r#""#),
            (
                r#"INSERT INTO g(g) VALUES('rebuild');"#,
                r#"ERR:'rebuild' may not be used with a contentless fts5 table"#,
            ),
            (
                r#"DELETE FROM g WHERE rowid = 1;"#,
                r#"ERR:cannot DELETE from contentless fts5 table: g"#,
            ),
            (
                r#"UPDATE g SET a = 'z' WHERE rowid = 1;"#,
                r#"ERR:cannot UPDATE contentless fts5 table: g"#,
            ),
            (
                r#"INSERT INTO g(g, rowid, a) VALUES('delete', 1, 'x y');"#,
                r#""#,
            ),
            (
                r#"INSERT INTO g(g, rowid, a) VALUES('delete', 1, 'x y');"#,
                r#"ERR:database disk image is malformed"#,
            ),
            (
                r#"SELECT k, v FROM f_config ORDER BY k;"#,
                r#"PGSZ|1000
rank|nosuchfn(1, 2)
secure-delete|1
version|4"#,
            ),
            (
                r#"SELECT rowid, rank FROM f WHERE f MATCH 'x';"#,
                r#"ERR:no such function: nosuchfn"#,
            ),
            (r#"SELECT count(*) FROM g WHERE g MATCH 'x';"#, r#"0"#),
        ],
        post: &[],
        checks_after: &[],
    });
}

/// a row that is in the index but not in the content table is an error only where C looks the row up (fts5SeekCursor)
#[test]
fn external_content_missing_row() {
    run_case(&Case {
        create: &[
            r#"CREATE TABLE src(id INTEGER PRIMARY KEY, a, b);"#,
            r#"CREATE VIRTUAL TABLE f USING fts5(a, b, content='src', content_rowid='id');"#,
        ],
        writes: &[
            r#"INSERT INTO src VALUES(1, 'x y', 'z'), (2, 'x', 'w'), (3, 'q', 'x');"#,
            r#"INSERT INTO f(rowid, a, b) SELECT id, a, b FROM src;"#,
            r#"DELETE FROM src WHERE id = 2;"#,
        ],
        image: &[],
        checks: &[
            (
                r#"SELECT rowid FROM f WHERE f MATCH 'x' ORDER BY rowid;"#,
                r#"1
2
3"#,
            ),
            (
                r#"SELECT rowid, printf('%.6g', bm25(f)) FROM f WHERE f MATCH 'x' ORDER BY rowid;"#,
                r#"1|-8.95349e-07
2|-1.06207e-06
3|-1.06207e-06"#,
            ),
            (
                r#"SELECT rowid, a FROM f WHERE f MATCH 'x' ORDER BY rowid;"#,
                r#"ERR:fts5: missing row 2 from content table 'main'.'src'"#,
            ),
            (
                r#"SELECT rowid, highlight(f, 0, '[', ']') FROM f WHERE f MATCH 'x' AND rowid = 2;"#,
                r#"ERR:database disk image is malformed"#,
            ),
            (r#"SELECT rowid, a FROM f WHERE rowid = 2;"#, r#""#),
            (
                r#"SELECT rowid, highlight(f, 0, '[', ']') FROM f WHERE f MATCH 'x' AND rowid = 1;"#,
                r#"1|[x] y"#,
            ),
            (r#"INSERT INTO f(f) VALUES('integrity-check');"#, r#""#),
            (
                r#"INSERT INTO f(f, rank) VALUES('integrity-check', 1);"#,
                r#"ERR:database disk image is malformed"#,
            ),
        ],
        post: &[],
        checks_after: &[],
    });
}
